use std::env;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};

fn respond(mut stream: TcpStream) {
    let mut request = [0_u8; 1024];
    let _ = stream.read(&mut request);
    let body = "<!doctype html><html><meta charset='utf-8'><title>Rust workspace</title><body><h1>Hello from Jahaziel</h1><p>Edit src/main.rs and reload this preview.</p></body></html>\n";
    let response = format!("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}", body.len(), body);
    let _ = stream.write_all(response.as_bytes());
}

fn main() -> std::io::Result<()> {
    let port = env::var("PORT").unwrap_or_else(|_| "8080".to_string());
    let listener = TcpListener::bind(format!("0.0.0.0:{port}"))?;
    println!("Listening on 0.0.0.0:{port}");
    for connection in listener.incoming() {
        if let Ok(stream) = connection { respond(stream); }
    }
    Ok(())
}
